    peak_force=0.; min_angle=1.; max_angle=0.; violations=0.; handle_contacts=0
    def step_target(target,gain=.7):
        nonlocal peak_force,min_angle,max_angle,violations,handle_contacts
        s.step(action_to(target,orientation,1,gain))
        min_angle=min(min_angle,float(d.qpos[hj])); max_angle=max(max_angle,float(d.qpos[hj]))
