                    f=np.zeros(6); mujoco.mj_contactForce(m,d,i,f)
                    peak_force=max(peak_force,float(np.linalg.norm(f[:3])))
                    handle_contacts+=1
    for _ in range(n1):step_target([.35,-2.03,1.13])
    for _ in range(n2):step_target([.0795,-2.09,hover_z])
    for _ in range(press_max):
        step_target([.0795,press_y,press_z])
        if d.qpos[hj]<threshold:break
    press_end=len(s.actions); angle_press=float(d.qpos[hj])
    for _ in range(nr):step_target([.25,-2.06,1.10],.2)
    h=s.hold_targets()
    for _ in range(settle):s.step(h)
    touches=[(m.geom(c.geom1).name,m.geom(c.geom2).name) for c in d.contact if ((m.geom(c.geom1).name.startswith(('robot0_','gripper0_'))) != (m.geom(c.geom2).name.startswith(('robot0_','gripper0_'))))]
    result=dict(tag=tag,pitch=pitch,n1=n1,n2=n2,nr=nr,hover_z=hover_z,press_y=press_y,press_z=press_z,threshold=threshold,settle=settle,steps=len(s.actions),success=s.check()['success'],angle=float(d.qpos[hj]),press_end=press_end,angle_press=angle_press,min_angle=min_angle,max_angle=max_angle,peak_handle_force=peak_force,joint_limit_excess=violations,final_contacts=touches,eef=d.site_xpos[sid].tolist())
    s.save_trajectory(path=f'/app/output/candidate_{tag}.npz')
    with open('/app/output/sweep_results.jsonl','a') as f:f.write(json.dumps(result)+'\n')
    print('RESULT',json.dumps(result),flush=True)
    return result
